mapper.select:
select 

from MST_EXCHARGE_QUOTE


		EXCHARGE_CODE like concat(concat('%', #{exchargeCode,jdbcType=VARCHAR}),'%')


	  and DATE_FORMAT(TRADE_DATE,'%Y-%m-%d') >= #{tradeDateBegin}  


	  and DATE_FORMAT(TRADE_DATE,'%Y-%m-%d') <= #{tradeDateEnd}  			 


	 and DATE_FORMAT(TRADE_DATE,'%Y-%m-%d') = #{tradeDate}  			 


order by  exchargeCode,tradeDate
